body:
A temporary workaround (create a new plugin and use this code):
```
@tool
extends EditorPlugin

var last_scene_is_null := true

func __process_mat(mat:Material):
	if mat:
		var props := mat.get_property_list()
		var prop_names:PackedStringArray = PackedStringArray()
		prop_names.resize(props.size())
		for i in range(props.size()):
			var name:String = props[i]['name']
			if name.begins_with('shader_parameter/'):
				mat[name] = mat[name]
		if mat.next_pass:
			__process_mat(mat.next_pass)

func __refresh_mats_of_node(n:Node):
	if n:
		var ginst := n as GeometryInstance3D
		if ginst:
			if ginst.material_override:
				__process_mat(ginst.material_override)
			if ginst.material_overlay:
				__process_mat(ginst.material_overlay)
		var mesh := n as MeshInstance3D
		if mesh:
			for i in range(mesh.get_surface_override_material_count()):
				__process_mat(mesh.get_surface_override_material(i))
				__process_mat(mesh.mesh.surface_get_material(i))
		for c in n.get_children():
			__refresh_mats_of_node(c)

func __on_scene_change(scene:Node):
	if scene:
		last_scene_is_null = false
	else:
		last_scene_is_null = true
	__refresh_mats_of_node(scene)

func _physics_process(_delta: float) -> void:
	if last_scene_is_null:
		var root := EditorInterface.get_edited_scene_root()
		if root:
			last_scene_is_null = false
			__on_scene_change(root)

func _enable_plugin() -> void:
	# Add autoloads here.
	pass


func _disable_plugin() -> void:
	# Remove autoloads here.
	pass


func _enter_tree() -> void:
	# Initialization of the plugin goes here.
	last_scene_is_null = true
	scene_changed.connect(__on_scene_change)


func _exit_tree() -> void:
	# Clean-up of the plugin goes here.
	scene_changed.disconnect(__on_scene_change)

```

It simply finds all materials when the edited scene is changed (have to use that `last_scene_is_null` in conjunction with `_physics_process` to capture the case where a scene is opened when no other scene is already opened), and re-assign all the shader parameters of the material in question.

I may have missed some other cases where a material is referenced, but it has covered my own use cases. You can easily extend the `__refresh_mats_of_node` method to cover additional cases.
